import { APIError, uploadAttachment, type Attachment } from "@/api/client";
import { getLocalFilePath } from "@/lib/desktopBridge";
import { newClientID } from "@/lib/id";
import type { DraftPartOrderItem } from "@/lib/submitParts";

export type DraftAttachment = {
  id: string;
  name: string;
  size: number;
  status: "uploading" | "uploaded" | "error";
  attachment?: Attachment;
  previewURL?: string;
  file?: File;
  upload?: { sessionID: string; origin?: "temp"; sourcePath?: string };
  errorKey?: "composer.uploadFailed" | "composer.draftUploadUnavailable";
};

type Update<T> = (update: (current: T[]) => T[]) => void;

// The setters capture one draft key. Each attempt updates only its own immutable
// item, so switching drafts, removing a card or replacing it cannot revive it.
export function createAttachmentUploads({ token, sessionID, setAttachments, setPartOrder, onError }: {
  token: string;
  sessionID: string;
  setAttachments: Update<DraftAttachment>;
  setPartOrder: Update<DraftPartOrderItem>;
  onError: (item: DraftAttachment) => void;
}) {
  async function upload(attempt: DraftAttachment) {
    const { file, upload: target } = attempt;
    if (!file || !target) return;
    try {
      const { sessionID: targetSessionID, ...options } = target;
      const attachment = await uploadAttachment(token, targetSessionID, file, options);
      // Drop the retry payload after success; the uploaded attachment is now the
      // source for submission. The preview lives until removal/acknowledgement.
      const { file: _file, upload: _target, errorKey: _error, ...retained } = attempt;
      setAttachments(current => !current.includes(attempt) ? current : current.map(item => item === attempt
        ? { ...retained, attachment, name: attachment.name, size: attachment.size, status: "uploaded" }
        : item));
    } catch (error) {
      const failed: DraftAttachment = { ...attempt, status: "error", errorKey: target.sessionID === "draft" && error instanceof APIError && error.status === 404 ? "composer.draftUploadUnavailable" : "composer.uploadFailed" };
      let retained = false;
      setAttachments(current => !current.includes(attempt) ? current : current.map(item => {
        if (item !== attempt) return item;
        retained = true;
        return failed;
      }));
      if (retained) onError(failed);
    }
  }

  function addFiles(files: File[], options?: { origin?: "temp"; sourcePaths?: string[]; uploadSessionID?: string }) {
    const items = files.flatMap((file, index): DraftAttachment[] => {
      if (!file.size) return [];
      const sourcePath = (options?.sourcePaths?.[index] || getLocalFilePath(file)).trim();
      return [{
        id: newClientID(), file, name: file.name, size: file.size, status: "uploading",
        previewURL: isImageAttachmentLike(file.type, file.name) ? URL.createObjectURL(file) : undefined,
        upload: { sessionID: options?.uploadSessionID || sessionID, ...(options?.origin ? { origin: options.origin } : {}), ...(sourcePath ? { sourcePath } : {}) },
      }];
    });
    if (!items.length) return;
    setAttachments(current => [...current, ...items]);
    setPartOrder(current => [...current, ...items.map(item => ({ type: "attachment" as const, id: item.id }))]);
    for (const item of items) void upload(item);
  }

  function retryAttachment(id: string) {
    let attempt: DraftAttachment | undefined;
    setAttachments(current => {
      const item = current.find(item => item.id === id && item.status === "error" && item.file && item.upload);
      if (!item) return current;
      attempt = { ...item, status: "uploading", errorKey: undefined };
      return current.map(entry => entry === item ? attempt! : entry);
    });
    // Claim the item synchronously: a second click sees uploading and is ignored.
    if (attempt) void upload(attempt);
  }

  return { addFiles, retryAttachment };
}

export function isImageAttachmentLike(mime: string | undefined, name: string) {
  const cleaned = (mime || "").toLowerCase();
  if (cleaned.startsWith("image/") && cleaned !== "image/svg+xml") {
    return true;
  }
  return /\.(png|jpe?g|gif|webp)$/i.test(name);
}

