  state.setPartOrder(key, [{ type: "attachment", id: "sent" }, { type: "local_folder", id: "sent-folder" }]);
}
function prepare(key = "chat") {
  const draft = content(key), text = draft.text.trim();
  return state.prepareSubmission(key, { text, parts: buildDraftSubmitParts(text, draft.attachments, draft.localFolders, draft.partOrder),
    provider: "mock", model: "mock", projectID: "project", reasoningEffort: "high", title: "" });
