    const held = Promise.withResolvers<void>(), released = Promise.withResolvers<void>();
    const hold = async (stage: string) => { if (stage === phase) { held.resolve(); await released.promise; } };
    const previous = globalThis.fetch;
    let navigations = 0;
    globalThis.fetch = async (url, init) => {
      const path = String(url), body = init?.body ? JSON.parse(String(init.body)) : {};
      if (path.endsWith("/sessions")) { await hold("create"); return Response.json(created); }
