import assert from "node:assert/strict";
import { beforeEach, test } from "node:test";
import { createTestViteServer } from "./vite-test-server.ts";

const server = await createTestViteServer();
const { useSessionDraftStore, queuedDraftKey } = await server.ssrLoadModule("/src/state/sessionDraftStore.ts");
const { buildDraftSubmitParts } = await server.ssrLoadModule("/src/lib/submitParts.ts");
const state = useSessionDraftStore.getState(), key = queuedDraftKey("a", "queued");
const current = () => useSessionDraftStore.getState().drafts[key];
const attachment = (id: string) => ({ id, name: id + ".png", size: 3, status: "uploaded", previewURL: "blob:" + id,
  attachment: { id, name: id + ".png", size: 3, mime: "image/png", attachmentKey: id, url: "/" + id } });
const input = { clientMessageID: "queued", text: "original", parts: [{ type: "text", text: "original" }] };
function seed() {
  state.beginQueueEdit("a", input);
  state.setText(key, "saved version");
  state.setAttachments(key, [attachment("saved")]);
  state.setLocalFolders(key, [{ id: "folder", name: "folder", path: "/tmp/folder" }]);
  state.setProjectReferences(key, [{ id: "ref", rootID: "root", path: "README.md", name: "README.md", kind: "file" }]);
  state.setStudioReferences(key, [{ id: "studio", kind: "widget", itemID: "studio", name: "studio", revision: "v1" }]);
  state.setPartOrder(key, [{ type: "attachment", id: "saved" }, { type: "local_folder", id: "folder" }, { type: "project_reference", id: "ref" }]);
}
beforeEach(() => useSessionDraftStore.setState({ drafts: {}, queueEdits: {} }));

test("confirmed unchanged queue save closes only that editor, releases preview once and preserves ordinary drafts", t => {
  const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
  state.setText("a", "independent ordinary draft"); state.setText("b", "other session"); seed();
  const snapshot = current();
  assert.equal(state.acknowledgeQueueEdit("a", "queued", snapshot), true);
  assert.equal(current(), undefined); assert.equal(useSessionDraftStore.getState().queueEdits.a, undefined);
  assert.equal(state.ensure("a").text, "independent ordinary draft"); assert.equal(state.ensure("b").text, "other session");
  assert.equal(state.acknowledgeQueueEdit("a", "queued", snapshot), false);
  assert.deepEqual(revoked.mock.calls.map(call => call.arguments), [["blob:saved"]]);
});

for (const [label, edit] of [
  ["later text", () => state.setText(key, "later text")],
  ["pending attachment", () => state.setAttachments(key, items => [...items, { id: "later", name: "later.txt", size: 3, status: "uploading", file: new File(["abc"], "later.txt") }])],
  ["removed attachment", () => state.setAttachments(key, [])],
  ["replaced attachment", () => state.setAttachments(key, [attachment("saved")])],
  ["folder", () => state.setLocalFolders(key, [])],
  ["project reference", () => state.setProjectReferences(key, [])],
  ["Studio reference revision", () => state.setStudioReferences(key, items => [{ ...items[0], revision: "v2" }])],
  ["part order", () => state.setPartOrder(key, items => [...items].reverse())],
] as const) {
  test(`acknowledgement preserves the full replacement draft after ${label}`, t => {
    const revoked = t.mock.method(URL, "revokeObjectURL", () => {});
    seed(); const snapshot = current(); edit(); const newer = current();
    assert.equal(state.acknowledgeQueueEdit("a", "queued", snapshot), false);
    assert.equal(current(), newer); assert.equal(useSessionDraftStore.getState().queueEdits.a, "queued");
    assert.equal(revoked.mock.callCount(), 0);
    // This draft remains a replacement of the existing queued input, not a partial append.
    const parts = buildDraftSubmitParts(newer.text, newer.attachments, newer.localFolders, newer.partOrder, newer.projectReferences);
    assert.equal(parts.find(part => part.type === "text").text, newer.text);
    assert.equal(state.acknowledgeQueueEdit("a", "queued", newer), true);
    assert.equal(current(), undefined);
  });
}

test("old replies cannot close another queue item or a reopened incarnation of the same item", () => {
  seed(); const old = current();
  state.beginQueueEdit("a", { ...input, clientMessageID: "different" });
  assert.equal(state.acknowledgeQueueEdit("a", "queued", old), false);
  assert.equal(useSessionDraftStore.getState().queueEdits.a, "different");
  state.endQueueEdit("a"); state.beginQueueEdit("a", input);
  const reopened = current(); assert.notEqual(reopened.clientMessageID, old.clientMessageID);
  assert.equal(state.acknowledgeQueueEdit("a", "queued", old), false); assert.equal(current(), reopened);
  state.endQueueEdit("a"); assert.equal(state.acknowledgeQueueEdit("a", "queued", reopened), false);
});

test("explicit send-as-new uses a fresh identity and preserves subsequent edits without touching the ordinary draft", () => {
  state.setText("a", "ordinary draft"); seed();
  const submission = state.prepareSubmission(key);
  assert.notEqual(submission.clientMessageID, input.clientMessageID);
  assert.equal(state.prepareSubmission(key), submission, "unconfirmed unchanged submit retries remain idempotent");
  state.setText(key, "typed during send-as-new");
  assert.equal(state.acknowledgeQueueEdit("a", "queued", submission), false);
  state.acknowledgeSubmission(key, submission);
  assert.equal(current().text, "typed during send-as-new"); assert.deepEqual(current().attachments, []);
  assert.equal(state.ensure("a").text, "ordinary draft");
  const next = state.prepareSubmission(key);
  assert.notEqual(next.clientMessageID, submission.clientMessageID);
  assert.equal(state.acknowledgeQueueEdit("a", "queued", next), true);
  assert.equal(current(), undefined); assert.equal(state.ensure("a").text, "ordinary draft");
});
